/* Runs each module over recorded inputs between two marker calls, so that
 * scripts/count_instructions.py can count the instructions spent inside the
 * library functions per call. bench_inputs.h is generated by that script. */
#include <stdint.h>

#include "jd_detector.h"
#include "jd_emf.h"
#include "jd_mras.h"
#include "semihost.h"
#include "bench_inputs.h"

volatile float sink;

__attribute__((noinline)) void bench_begin(int id)
{
    __asm__ volatile("" : : "r"(id) : "memory");
}

__attribute__((noinline)) void bench_end(int id)
{
    __asm__ volatile("" : : "r"(id) : "memory");
}

int main(void)
{
    static jd_mras_t ms;
    static jd_emf_t es;
    static jd_det_t det;

    jd_mras_init(&ms, BENCH_TH0, BENCH_W0, 0.0f, BENCH_IQ0);
    bench_begin(1);
    for (uint32_t k = 0u; k < BENCH_N; k++) {
        jd_mras_step(&ms, &bench_mras, bench_in[k][0], bench_in[k][1],
                     bench_in[k][2], bench_in[k][3]);
    }
    bench_end(1);
    sink = ms.w;

    jd_emf_init(&es, BENCH_TH0, BENCH_W0, 0.0f, BENCH_IQ0, BENCH_PSI);
    bench_begin(2);
    for (uint32_t k = 0u; k < BENCH_N; k++) {
        jd_emf_step(&es, &bench_emf, bench_in[k][0], bench_in[k][1],
                    bench_in[k][2], bench_in[k][3]);
    }
    bench_end(2);
    sink = es.wi;

    jd_det_init(&det, BENCH_W0 / BENCH_P);
    int fired = 0;
    bench_begin(3);
    for (uint32_t k = 0u; k < BENCH_N; k++) {
        fired += jd_det_step(&det, &bench_det, bench_wm[k]);
    }
    bench_end(3);
    sink = (float)fired;

    semihost_puts("bench done\n");
    return 0;
}
